  links: [['http://hsr.hoyoverse.com', 'Honkai: Star Rail 98 — официальный сайт'], ['http://www.astralwiki98.ru', 'АстралВики ’98 — база знаний'], ['http://www.kovcheg98.ru', 'Ковчег — тир-листы и конструктор отряда']],
