  links: [['http://www.igromania.ru', 'Журнал «Игромания»: демоверсия «Корованы Demo»'], ['http://www.steampowered.com', 'Каталог Steam: Kirill The Game'], ['http://forum.games98.com', 'Форум GamerZone']],
